import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BfI5QxtK.js";const u=JSON.parse('{"title":"Blur during client animations","description":"","frontmatter":{},"headers":[],"relativePath":"blur-fades.md","filePath":"blur-fades.md"}'),n={name:"blur-fades.md"};function o(r,e,d,l,h,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="blur-during-client-animations" tabindex="-1">Blur during client animations <a class="header-anchor" href="#blur-during-client-animations" aria-label="Permalink to &quot;Blur during client animations&quot;">​</a></h1><p>A translucent panel still needs full blur while it is visible. During a fade-out, both the panel and its blur should disappear. Pixel transparency alone cannot tell Gnoblin which of those two cases is happening.</p><p>This page explains how shell developers mark animated regions. For normal desktop settings, see <a href="/gnoblin/config/animations">animations</a>.</p><h2 id="whole-window-fades" tabindex="-1">Whole-window fades <a class="header-anchor" href="#whole-window-fades" aria-label="Permalink to &quot;Whole-window fades&quot;">​</a></h2><p>Let Gnoblin animate the whole surface using a <a href="/gnoblin/config/animations#per-surface-animations">layer animation</a>. It fades the window and the blur behind it together. Do not also fade the client buffer for the same transition.</p><h2 id="items-sharing-one-buffer" tabindex="-1">Items sharing one buffer <a class="header-anchor" href="#items-sharing-one-buffer" aria-label="Permalink to &quot;Items sharing one buffer&quot;">​</a></h2><p>Use <code>gnoblin_blur_fade_manager_v1</code> for independent item fades. Commit each item&#39;s logical rectangle and animation opacity with the buffer.</p><p>The protocol does not enable blur or change foreground pixels. It is optional and unavailable outside Gnoblin mode.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Regions per surface</td><td>32</td></tr><tr><td>Coordinates</td><td>Signed 24.8 fixed point, within ±65536</td></tr><tr><td>Opacity</td><td>0–1</td></tr><tr><td>Clear metadata</td><td>Empty array</td></tr></tbody></table><p>Do not submit both an ancestor and descendant for the same animation. Group overlapping foreground elements and their shadows before applying opacity.</p><p>Bingux submits metadata during Qt scene synchronisation, including client decoration offsets. Settled windows clear it and use the ordinary blur cache.</p><h2 id="foreground-details" tabindex="-1">Foreground details <a class="header-anchor" href="#foreground-details" aria-label="Permalink to &quot;Foreground details&quot;">​</a></h2><p>Icons and separators can be more opaque than the panel. Their alpha must not create gaps in the backdrop.</p><p>The fallback mask only estimates adjacent material at a silhouette edge with matching colour. Explicit <a href="./background-effects">standard regions</a> give the client direct control of that shape.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_TEST_DBUS_CLIENT=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tests/test-blur-fade-protocol.sh&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bash </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/run-gnome-shell.sh</span></span></code></pre></div><p>Repeat with <code>GNOBLIN_TEST_MODE=user</code> for stock-session isolation.</p><p>For client fades, run <code>tests/test-blur-fade.py</code> with <code>GNOBLIN_TEST_CLIENT_FADE=1</code> and a Qt-matched <code>QS_TEST_BIN</code>.</p><p>Bingux&#39;s <code>tests/panel-blur-fade.py</code> and <code>tests/shared-buffer-fades.py</code> cover intermediate opacity, closing and reversal. They require its effects plugin in the matching Quickshell import path.</p><p><code>tests/test-blur-detail-coverage.py</code> checks foreground details. Optional <code>STEAM_ICON</code> and <code>LOCALSEND_ICON</code> paths add real icon samples; synthetic cases always run.</p>`,20)])])}const f=a(n,[["render",o]]);export{u as __pageData,f as default};
